/* From Uiverse.io by MuhammadHasann  - Tags: subscription, purple, minimalist, card, rounded, smooth */
.__UIV_SCOPE__ .card {
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1rem;
  width: 14rem;
  height: auto;
  background-color: rgb(122, 48, 143);
  background-image: radial-gradient(
      circle at 0% 0%,
      rgb(37, 7, 44) 15%,
      rgba(0, 0, 0, 0) 75%
    ),
    radial-gradient(
      circle at 100% 100%,
      rgb(25, 2, 31, 0.9) 15%,
      rgba(0, 0, 0, 0) 150%
    ),
    linear-gradient(
      135deg,
      rgba(24, 8, 28, 0) 0%,
      rgb(122, 48, 143) 50%,
      rgba(24, 8, 28, 0) 100%
    );
  border-radius: 0.5rem;
}

.__UIV_SCOPE__ .card::before {
  content: "";
  position: absolute;
  top: 1rem;
  right: 1rem;
  width: 2rem;
  height: 2rem;
  background-color: rgb(122, 48, 143);
  background-image: linear-gradient(
    0deg,
    rgba(118, 42, 180, 1) 0%,
    rgb(199, 95, 228) 75%
  );
  border-radius: 9999px;
  box-shadow: 0 1px 5px 3px rgb(199, 95, 228), 0 0 30px 5px rgb(199, 95, 228);
}

.__UIV_SCOPE__ .card .title {
  font-size: 1rem;
  color: white;
  font-weight: 600;
}

.__UIV_SCOPE__ .card .pricing {
  font-size: 1.5rem;
  color: white;
  font-weight: 600;
}

.__UIV_SCOPE__ .card .pricing .pricing-time,
.__UIV_SCOPE__ .card .sub-title {
  font-size: 0.75rem;
  color: rgb(184, 132, 199);
  font-weight: 500;
}

.__UIV_SCOPE__ .card .list {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.75rem;
  color: white;
  font-weight: 500;
  list-style: none;
}

.__UIV_SCOPE__ .card .list .list-item .check {
  margin-right: 0.25rem;
  font-size: 1rem;
  color: rgb(199, 95, 228);
  font-weight: 900;
}

.__UIV_SCOPE__ .card .button {
  overflow: hidden;
  cursor: pointer;
  position: relative;
  margin-top: 0.5rem;
  padding: 0.5rem 0.75rem;
  width: 100%;
  height: fit-content;
  background-color: rgb(122, 48, 143);
  font-size: 0.75rem;
  color: white;
  border: none;
  border-radius: 0.5rem;
  box-shadow: 0px 0px 2px 1px rgb(122, 48, 143);
  transition: all 0.3s cubic-bezier(1, 0, 0, 1);
}

.__UIV_SCOPE__ .card .button .text-button {
  position: relative;
  z-index: 10;
}

.__UIV_SCOPE__ .card .button::before,
.__UIV_SCOPE__ .card .button::after {
  content: "";
  position: absolute;
  top: 0;
  width: 100%;
  height: 100%;
  transition: all 0.3s ease-in-out;
}
.__UIV_SCOPE__ .card .button::before {
  left: 0;
  background-image: radial-gradient(
    circle at 0% 45%,
    rgba(16, 5, 36, 1) 19%,
    rgba(16, 5, 36, 0.26) 46%,
    rgba(16, 5, 36, 0) 100%
  );
}
.__UIV_SCOPE__ .card .button::after {
  right: 0;
  background-image: radial-gradient(
    circle at 100% 45%,
    rgba(16, 5, 36, 1) 19%,
    rgba(16, 5, 36, 0.26) 46%,
    rgba(16, 5, 36, 0) 100%
  );
}

.__UIV_SCOPE__ .card .button:hover {
  box-shadow: 0px 0px 20px 0 rgb(122, 48, 143);
}

.__UIV_SCOPE__ .card .button:hover::before,
.__UIV_SCOPE__ .card .button:hover::after {
  width: 0;
  opacity: 0;
}
